style.css:
@-moz-document domain("open.spotify.com") {
/* ================================================================
   EDIT THESE — quick tweaks
   ================================================================ */
:root {
  --rg-accent: #9fe3c0;                 /* mint, picked from the plants */
  --rg-accent-soft: rgba(159, 227, 192, .18);
  --rg-glass: rgba(20, 38, 33, .38);    /* panel tint: raise last number = more solid */
  --rg-glass-strong: rgba(18, 32, 28, .55);
  --rg-blur: 16px;                      /* blur strength (lower = lighter on memory/GPU) */
  --rg-sticky-tint: transparent;        /* sticky bars while scrolling; e.g. rgba(14,30,25,.6) for a solid-ish bar */
  --rg-side-tint: transparent;          /* left library + player bar; e.g. rgba(8,14,12,.3) to darken */
  --rg-main-tint: transparent;          /* main content area; e.g. rgba(10,22,18,.25) to darken it */
  --rg-radius: 20px;                    /* panel corner radius */
  --rg-ease: cubic-bezier(.22, 1, .36, 1);
  --rg-font: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "Inter", "Segoe UI", system-ui, sans-serif;
}

/* ================================================================
   Spotify's own colour tokens -> glass
   ================================================================ */
:root, html, body, .Root, .encore-dark-theme, .encore-layout-themes, .encore-base-set {
  --background-base: rgba(255, 255, 255, 0) !important;
  --background-highlight: rgba(255, 255, 255, .09) !important;
  --background-press: rgba(255, 255, 255, .05) !important;
  --background-elevated-base: rgba(255, 255, 255, .09) !important;
  --background-elevated-highlight: rgba(255, 255, 255, .15) !important;
  --background-elevated-press: rgba(255, 255, 255, .07) !important;
  --background-tinted-base: rgba(255, 255, 255, .07) !important;
  --background-tinted-highlight: rgba(255, 255, 255, .13) !important;
  --background-tinted-press: rgba(255, 255, 255, .04) !important;
  --text-base: #fff !important;
  --text-subdued: rgba(255, 255, 255, .66) !important;
  --text-bright-accent: var(--rg-accent) !important;
  --essential-bright-accent: var(--rg-accent) !important;
  --essential-base: #fff !important;
  --essential-subdued: rgba(255, 255, 255, .5) !important;
  --decorative-base: #fff !important;
  --decorative-subdued: rgba(255, 255, 255, .16) !important;
  --encore-body-font-stack: var(--rg-font) !important;
  --encore-title-font-stack: var(--rg-font) !important;
}

/* ================================================================
   Typography — SF Pro where available, Inter / system elsewhere
   ================================================================ */
body, button, input, textarea, select, a, p, span, div, h1, h2, h3, h4, h5, h6 {
  font-family: var(--rg-font) !important;
}
body {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  letter-spacing: -.011em;
}
h1, h2, h3, [data-encore-id="type"][class*="Type__TypeElement-sc"] {
  letter-spacing: -.025em;
}

/* ================================================================
   Background: the rainy window
   ================================================================ */
html {
  background:
    radial-gradient(120% 90% at 50% 40%, transparent 40%, rgba(6, 16, 12, .5) 100%) fixed,
    linear-gradient(rgba(10, 6, 6, .1), rgba(10, 6, 6, .1)) fixed,
    url("data:image/webp;base64,") center / cover no-repeat fixed,
    #160c0b !important;
}
body, #main, .Root, .Root__top-container, .Root__globalNav, #global-nav-bar,
body > div, body > div > div, body > div > div > div,
.Root > div, .Root > div > div, body > div > div > div > div,
[class*="Root__top-container"], [class*="Root__globalNav"] {
  background: transparent !important;
  background-color: transparent !important;
}


/* ================================================================
   Glass panels
   ================================================================ */
#Desktop_LeftSidebar_Id, #main-view, #Desktop_PanelContainer_Id, [data-testid="now-playing-bar"],
.Root__nav-bar, .Root__main-view, .Root__right-sidebar, .Root__now-playing-bar {
  background: var(--rg-glass) !important;
  -webkit-backdrop-filter: blur(var(--rg-blur));
  backdrop-filter: blur(var(--rg-blur));
  border: 1px solid rgba(255, 255, 255, .14);
  border-radius: var(--rg-radius);
  contain: paint;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, .22),
    inset 0 0 0 .5px rgba(255, 255, 255, .05),
    0 8px 24px -10px rgba(0, 0, 0, .4);
  overflow: hidden;
}
[data-testid="now-playing-bar"], .Root__now-playing-bar { border-radius: 24px; }

/* main content area: transparent, no blur (cheapest and shows the window) */
#main-view {
  background: var(--rg-main-tint) !important;
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  box-shadow: none;
  border-color: rgba(255, 255, 255, .1);
  text-shadow: 0 1px 3px rgba(0, 0, 0, .6);
}
#main-view section { background: transparent !important; }

/* left library + bottom player bar: clear like the main view */
#Desktop_LeftSidebar_Id,
[data-testid="now-playing-bar"],
.Root__now-playing-bar {
  background: var(--rg-side-tint) !important;
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  box-shadow: none;
  border-color: rgba(255, 255, 255, .1);
  text-shadow: 0 1px 3px rgba(0, 0, 0, .6);
}

/* inner containers stay clear so the glass shows through */
.main-view-container,
.main-view-container__scroll-node-child,
.main-home-content,
.main-nowPlayingBar-container,
.main-yourLibraryX-libraryContainer,
.main-yourLibraryX-libraryItemContainer,
.main-topBar-container,
#Desktop_LeftSidebar_Id > *,
#Desktop_LeftSidebar_Id nav,
#Desktop_PanelContainer_Id > *,
[data-testid="now-playing-bar"] > * {
  background-color: transparent !important;
}

/* Spotify colours headers/bars per page (inline background or --background-* vars): clear it */
#main-view [style*="--background"] {
  --background-base: transparent !important;
  --background-highlight: rgba(255, 255, 255, .1) !important;
  --background-press: rgba(255, 255, 255, .05) !important;
  --background-tinted-base: rgba(255, 255, 255, .07) !important;
}
#main-view [style*="background"] {
  background-color: transparent !important;
}
/* artist / album / playlist pages: clear header colour layers
   (top 8 levels of the page; colour only; divs/sections/headers/main only, so buttons, chips, cards and images keep their look) */
#main-view .main-view-container__scroll-node-child > div,
#main-view .main-view-container__scroll-node-child > section,
#main-view .main-view-container__scroll-node-child > header,
#main-view .main-view-container__scroll-node-child > main,
#main-view .main-view-container__scroll-node-child > * > div,
#main-view .main-view-container__scroll-node-child > * > section,
#main-view .main-view-container__scroll-node-child > * > header,
#main-view .main-view-container__scroll-node-child > * > main,
#main-view .main-view-container__scroll-node-child > * > * > div,
#main-view .main-view-container__scroll-node-child > * > * > section,
#main-view .main-view-container__scroll-node-child > * > * > header,
#main-view .main-view-container__scroll-node-child > * > * > main,
#main-view .main-view-container__scroll-node-child > * > * > * > div,
#main-view .main-view-container__scroll-node-child > * > * > * > section,
#main-view .main-view-container__scroll-node-child > * > * > * > header,
#main-view .main-view-container__scroll-node-child > * > * > * > main,
#main-view .main-view-container__scroll-node-child > * > * > * > * > div,
#main-view .main-view-container__scroll-node-child > * > * > * > * > section,
#main-view .main-view-container__scroll-node-child > * > * > * > * > header,
#main-view .main-view-container__scroll-node-child > * > * > * > * > main,
#main-view .main-view-container__scroll-node-child > * > * > * > * > * > div,
#main-view .main-view-container__scroll-node-child > * > * > * > * > * > section,
#main-view .main-view-container__scroll-node-child > * > * > * > * > * > header,
#main-view .main-view-container__scroll-node-child > * > * > * > * > * > main,
#main-view .main-view-container__scroll-node-child > * > * > * > * > * > * > div,
#main-view .main-view-container__scroll-node-child > * > * > * > * > * > * > section,
#main-view .main-view-container__scroll-node-child > * > * > * > * > * > * > header,
#main-view .main-view-container__scroll-node-child > * > * > * > * > * > * > main,
#main-view .main-view-container__scroll-node-child > * > * > * > * > * > * > * > div,
#main-view .main-view-container__scroll-node-child > * > * > * > * > * > * > * > section,
#main-view .main-view-container__scroll-node-child > * > * > * > * > * > * > * > header,
#main-view .main-view-container__scroll-node-child > * > * > * > * > * > * > * > main {
  background-color: transparent !important;
  --background-base: transparent !important;
  --background-tinted-base: rgba(255, 255, 255, .06) !important;
}
/* scroll containers + any inline gradient overlay anywhere in the page */
#main-view .main-view-container,
#main-view .main-view-container__scroll-node,
#main-view [data-overlayscrollbars-viewport] {
  background-color: transparent !important;
  background-image: none !important;
}
/* inline gradient / sticky layers: colour only. Their background-image can be a real photo
   (the About card uses gradient + photo in one value), so images are never stripped here. */
#main-view [style*="gradient"],
#main-view [style*="sticky"] {
  background-color: transparent !important;
}
/* the blue action-bar band (found with the probe: absolute div, blue-to-clear gradient under the play/follow row).
   Spotify's class names change on updates; if the blue comes back, re-run the probe and send me the new class. */
#main-view [class~="rRzDzkFoPB1jsHaUjsDT"] {
  background-image: none !important;
  background-color: transparent !important;
}
/* gradient / banner layers at page-header level only (the About card photo further down is left alone) */
#main-view > * > * > * > div,
#main-view > * > * > * > section,
#main-view > * > * > * > header,
#main-view > * > * > * > * > div,
#main-view > * > * > * > * > section,
#main-view > * > * > * > * > header {
  background-image: none !important;
}
/* artist hero: Spotify paints a solid #121212 + black fade in an ::after over the photo (header level only) */
#main-view > * > * > [data-testid="background-image"] + div::after,
#main-view > * > * > * > [data-testid="background-image"] + div::after,
#main-view > * > * > * > * > [data-testid="background-image"] + div::after,
#main-view > * > * > [data-testid="background-image"] ~ div::after,
#main-view > * > * > * > [data-testid="background-image"] ~ div::after,
#main-view > * > * > * > * > [data-testid="background-image"] ~ div::after,
#main-view > * > * > [data-testid="background-image"]::after,
#main-view > * > * > * > [data-testid="background-image"]::after,
#main-view > * > * > * > * > [data-testid="background-image"]::after {
  background: none !important;
  background-color: transparent !important;
}
/* hide the big artist banner photo (header level only; the About card photo stays).
   Delete this block to bring the banner back. */
#main-view > * > * > [data-testid="background-image"],
#main-view > * > * > * > [data-testid="background-image"],
#main-view > * > * > * > * > [data-testid="background-image"],
#main-view > * > * > [data-testid="background-image"] + div,
#main-view > * > * > * > [data-testid="background-image"] + div,
#main-view > * > * > * > * > [data-testid="background-image"] + div {
  display: none !important;
}

/* solid page footer at the very bottom of artist/album pages */
#main-view [data-testid="footer-div"],
#main-view nav.footer {
  background-color: transparent !important;
}

/* play / follow action bar and the layers after it */
#main-view [data-testid="action-bar-row"],
#main-view [data-testid="action-bar-row"] + *,
#main-view [data-testid="action-bar-row"] ~ div {
  background-color: transparent !important;
  background-image: none !important;
}

/* keep hover highlights that the clearing above would otherwise remove */
#main-view [data-testid="tracklist-row"]:hover { background-color: rgba(255, 255, 255, .1) !important; }
#main-view [data-encore-id="card"]:hover { background-color: rgba(255, 255, 255, .08) !important; }

/* sticky bars (filters / titles while scrolling) */
#main-view [style*="sticky"],
#main-view [class*="topBar"],
#main-view [class*="trackListHeader"],
#main-view [data-testid="tracklist-header"] {
  background-color: var(--rg-sticky-tint) !important;
}

.main-topBar-background { background: var(--rg-sticky-tint) !important; }

/* search + home button */
[data-testid="search-input"],
[data-testid="home-button"] {
  background: rgba(255, 255, 255, .1) !important;
  border: 1px solid rgba(255, 255, 255, .14) !important;
  border-radius: 999px !important;
  transition: background-color .3s ease, border-color .3s ease;
}
[data-testid="search-input"]:hover,
[data-testid="home-button"]:hover { background: rgba(255, 255, 255, .16) !important; }
[data-testid="search-input"]:focus,
[data-testid="search-input"]:focus-within {
  background: rgba(255, 255, 255, .18) !important;
  border-color: var(--rg-accent) !important;
}

/* green accent buttons -> mint */
.encore-bright-accent-set {
  --background-base: var(--rg-accent) !important;
  --background-highlight: #b9efd3 !important;
  --background-press: #86cfa9 !important;
  --text-base: #0c1f18 !important;
}

/* floating menus, popovers and dialogs need more body than the panels */
#context-menu,
[role="menu"],
[role="listbox"],
[role="dialog"],
[role="tooltip"],
.main-contextMenu-menu {
  background: var(--rg-glass-strong) !important;
  -webkit-backdrop-filter: blur(20px);
  backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, .16) !important;
  border-radius: 16px !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .2), 0 22px 50px -10px rgba(0, 0, 0, .55) !important;
}
#context-menu,
[role="menu"] { animation: rg-pop .22s var(--rg-ease) both; transform-origin: top left; }

/* ================================================================
   Small, purposeful motion
   ================================================================ */
/* cards lift a little under the pointer */
[data-encore-id="card"],
.main-card-card {
  border-radius: 16px;
  transition: transform .45s var(--rg-ease), background-color .3s ease, box-shadow .45s var(--rg-ease);
}
[data-encore-id="card"]:hover,
.main-card-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 22px -10px rgba(0, 0, 0, .5), inset 0 1px 0 rgba(255, 255, 255, .18);
}
[data-encore-id="card"]:active,
.main-card-card:active { transform: translateY(-1px) scale(.985); }

/* track rows */
[data-testid="tracklist-row"] {
  border-radius: 12px;
  transition: background-color .25s ease;
}
[data-testid="tracklist-row"]:hover { background-color: rgba(255, 255, 255, .1) !important; }

/* play buttons: springy press */
[data-testid="control-button-playpause"],
button[data-encore-id="buttonPrimary"] {
  transition: transform .35s var(--rg-ease), box-shadow .35s ease, background-color .25s ease;
}
[data-testid="control-button-playpause"] { box-shadow: 0 6px 22px rgba(0, 0, 0, .35); }
[data-testid="control-button-playpause"]:hover,
button[data-encore-id="buttonPrimary"]:hover { transform: scale(1.07); }
[data-testid="control-button-playpause"]:active,
button[data-encore-id="buttonPrimary"]:active { transform: scale(.94); }

/* sidebar rows glide */
.Root__nav-bar a,
.Root__nav-bar [role="row"],
.Root__nav-bar [role="listitem"] {
  border-radius: 12px;
  transition: background-color .25s ease, transform .35s var(--rg-ease);
}

/* now-playing artwork */
[data-testid="now-playing-widget"] img,
[data-testid="cover-art-image"] {
  border-radius: 12px;
  box-shadow: 0 10px 28px rgba(0, 0, 0, .45);
}

/* progress + volume sliders */
.progress-bar,
[data-testid="progress-bar"],
[data-testid="playback-progressbar"] {
  --fg-color: #fff;
  --bg-color: rgba(255, 255, 255, .22);
  --is-active-fg-color: var(--rg-accent);
}

/* scrollbars */
.os-scrollbar-handle { background: rgba(255, 255, 255, .26) !important; border-radius: 999px !important; }
.os-scrollbar-handle:hover { background: rgba(255, 255, 255, .45) !important; }

::selection { background: var(--rg-accent-soft); }

@keyframes rg-rise {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: none; }
}
@keyframes rg-pop {
  from { opacity: 0; transform: scale(.96); }
  to   { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  #context-menu, [role="menu"] { animation: none !important; }
  [data-encore-id="card"], .main-card-card, [data-testid="control-button-playpause"] { transition: none !important; }
}
}
